index 968f4d152b4..4160abc119e 100644
--- a/mail/components/calendar/content/calendar-event-create-edit-dialog.mjs
+++ b/mail/components/calendar/content/calendar-event-create-edit-dialog.mjs
@@ -521,16 +521,20 @@ export class CalendarEventCreateEditDialog extends CalendarEventDialogSourceMixi

   /** Displays observed Save progress and failures for keyboard and speech users. */
   #renderSave() {
+    const body = this.querySelector(".calendar-event-create-edit-dialog-body");
+
+    // Store updates can arrive before connectedCallback creates the content.
+    if (!body) {
+      return;
+    }
+
     const operation = this.#createEditSession?.operation;
     const saving = operation?.status == "pending";

     // Block native dismissal too. Escape and native close requests must not
     // discard the draft while storage is changing the event.
     this.setAttribute("closedby", saving ? "none" : "closerequest");
-    this.querySelector(".calendar-event-create-edit-dialog-body").setAttribute(
-      "aria-busy",
-      saving ? "true" : "false"
-    );
+    body.setAttribute("aria-busy", saving ? "true" : "false");

     const button = this.querySelector(".calendar-event-save");
     if (button) {
